+import items from './items.json' with {type:'json'};
+
+const ALLOWED_ARGS = new Set(['query', 'offset', 'limit']);
+
+function isNonNegativeInteger(v) {
+  return typeof v === 'number' && Number.isInteger(v) && v >= 0;
+}
+
+export async function listTools() {
+  return [{
+    name: 'catalog_search',
+    description: 'Search the catalog by name with pagination.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string' },
+        offset: { type: 'integer', minimum: 0, default: 0 },
+        limit: { type: 'integer', minimum: 1, maximum: 5, default: 2 }
+      },
+      required: ['query'],
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'catalog_search') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  // Reject unknown/extra arguments.
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error('Unknown argument: ' + key);
+    }
+  }
+
+  const { query, offset = 0, limit = 2 } = args;
+
+  if (typeof query !== 'string') {
+    throw new Error('query must be a string');
+  }
+  if (!isNonNegativeInteger(offset)) {
+    throw new Error('offset must be a non-negative integer');
+  }
+  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
+    throw new Error('limit must be an integer between 1 and 5');
+  }
+
+  const needle = query.toLowerCase();
+  const matches = items.filter(it => it.name.toLowerCase().includes(needle));
+
+  const rows = matches.slice(offset, offset + limit);
+  const result = { rows };
+  if (offset + limit < matches.length) {
+    result.next_offset = offset + limit;
+  }
+
+  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
+}
